414	    /**
415	     * Loads the owner with the given id and, when it exists, produces the response through
416	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
417	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
418	     * the not-found response are written in exactly one place rather than copied into each method.
419	     *
420	     * @param ownerId the id of the owner to load
421	     * @param action builds the response for an existing owner
422	     * @param <T> the response body type
423	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
424	     */
425	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
426	        Owner owner = this.clinicService.findOwnerById(ownerId);
427	        if (owner == null) {
428	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
429	        }
430	        return action.apply(owner);
431	    }
432	
433	    /**
434	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
435	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} and
436	     * {@code capacityWarning} flags, the {@code identityKey} and the {@code possibleDuplicate} pair),
437	     * and re-applies the owner's
438	     * {@code membershipLevel} through the controller ({@link #membershipLevel(Owner)}). Both the
439	     * create endpoint and the single-owner read endpoint return their owner through this method, so
440	     * an owner is decorated identically on either path and each derived field is computed in exactly
441	     * one place.
442	     *
443	     * @param owner the persisted owner to represent
444	     * @return the owner DTO with its derived read-only fields populated
445	     */
446	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
447	        owner.setHouseholdSize(householdSize(owner));
448	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
449	        int membershipLevel = membershipLevel(owner);
450	        ownerDto.setMembershipLevel(membershipLevel);
451	        ownerDto.setOwnerSegment(ownerMapper.ownerSegment(owner, membershipLevel));
452	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
453	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
454	        ownerDto.setIdentityKey(identityKey(owner));
455	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
456	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
457	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
458	        ownerDto.setRiskFlag(riskFlag(owner));
459	        return ownerDto;
460	    }
461	
462	    /**
463	     * Derives the read-only {@code riskFlag} for an owner: {@code true} when any of the soft risk
464	     * signals hold, otherwise {@code false}. The owner is at risk when it is a possible duplicate
465	     * (its {@link Owner#getPossibleDuplicateOf() possibleDuplicateOf} is set), when its email domain
466	     * is {@linkplain DisposableEmailDomains#isDisposableAdjacent(String) disposable-adjacent}, or when
467	     * its city is over its soft capacity (the same {@link #capacityWarning(String)} band that raises
468	     * {@code capacityWarning}). Combining the existing signals here keeps {@code riskFlag} as a single
469	     * derived summary computed in exactly one place alongside the fields it aggregates.
470	     *
471	     * @param owner the persisted owner to assess
472	     * @return {@code true} when any risk signal holds, otherwise {@code false}
473	     */
474	    private boolean riskFlag(Owner owner) {
475	        return owner.getPossibleDuplicateOf() != null
476	            || disposableEmailDomains.isDisposableAdjacent(owner.getEmail())
477	            || capacityWarning(owner.getCity());
478	    }
479	
480	    /**
481	     * The {@code membershipLevel} reported for a single owner. Starts from the owner-local derivation
482	     * in {@link OwnerMapper#membershipLevel(Owner)} (the level from the owner's own membership points),
483	     * routed through the controller so the create audit log and the single-owner response agree on one
484	     * value. Unlike the mapper - which sees only the owner - the controller can reach the rest of the
485	     * clinic, so this is the single place a reported membership level is shaped by cross-owner context.
486	     *
487	     * <p>Household ceiling: the reported level is capped at one above the current maximum
488	     * {@linkplain #householdMemberLevel(Owner) level} among the owner's <em>existing</em>
489	     * {@link #householdMembers(Owner) household members} (those sharing its {@code householdId}, other
490	     * than the owner itself). With no existing household member no cap applies and the owner-local level
491	     * is reported unchanged. The cap uses each member's own owner-local level (not their reported,
492	     * capped level), so it depends only on the members' own points and cannot recurse.
493	     *
494	     * @param owner the owner whose reported membership level is wanted
495	     * @return the owner's membership level, capped at one above its household maximum
496	     */
497	    private Integer membershipLevel(Owner owner) {
498	        int ownLevel = ownerMapper.membershipLevel(owner);
499	        java.util.OptionalInt maxHouseholdLevel = householdMembers(owner).stream()
500	            .filter(member -> !java.util.Objects.equals(member.getId(), owner.getId()))
501	            .mapToInt(this::householdMemberLevel)
502	            .max();
503	        if (maxHouseholdLevel.isEmpty()) {
504	            return ownLevel;
505	        }
506	        return Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1);
507	    }
508	
509	    /**
510	     * The owner-local membership level of a household member, used only as an input to the household
511	     * ceiling in {@link #membershipLevel(Owner)}. The member's {@link Owner#getHouseholdSize()
512	     * household size} is set from its household before the level is derived, so the member's household
513	     * factor is accounted for exactly as it is when the member is reported on its own; the level itself
