652	    /**
653	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
654	     * the {@code memberId}.
655	     */
656	    private static final int MEMBER_ID_HASH_LENGTH = 8;
657	
658	    /**
659	     * Builds the unified {@code memberId} assigned to a newly created owner, formatted
660	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the owner's
661	     * {@linkplain #identityRegionCode(Owner) identity region code}; {@code FY} is the two-digit fiscal year of the owner's
662	     * (business-day-adjusted) {@code registrationDate} ({@link OwnerMapper#fiscalYearSegment(Owner)});
663	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
664	     * normalized telephone followed by its last name; and {@code CHK} is a single Luhn check digit over
665	     * the digits of {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSW261A2B3C4D5'}). When this base id
666	     * collides with an existing owner's {@code memberId}, {@code '-<n>'} is appended with the smallest
667	     * {@code n} of 2 or more that makes the result unique (e.g. {@code 'NSW261A2B3C4D5-2'}), so distinct
668	     * owners always receive distinct member ids.
669	     *
670	     * @param owner the owner being created, with its telephone already normalized and its registration
671	     *              date set
672	     * @return the formatted, de-duplicated member id
673	     */
674	    private String memberId(Owner owner) {
675	        String region = identityRegionCode(owner);
676	        String fiscalYear = ownerMapper.fiscalYearSegment(owner);
677	        String hash8 = sha256Hasher.hexPrefix(owner.getTelephone() + owner.getLastName(), MEMBER_ID_HASH_LENGTH);
678	        String core = region + fiscalYear + hash8;
679	        String base = core + Luhn.checkDigit(core);
680	        return deduplicate(base, Owner::getMemberId);
681	    }
