683	    /**
684	     * The canonical region code baked into an owner's identifiers, resolved from the owner's
685	     * {@code postcode} (falling back to its {@code city}) through the shared
686	     * {@link Region#code(String, String)} - the same one place an owner's postcode and city are turned
687	     * into a region code. This is the region code as it is embedded <em>inside</em> the identifiers an
688	     * owner is issued (the {@code REGION} segment of its {@link #memberId(Owner) memberId}), held in one
689	     * place so every identifier derived for an owner keys off the identical region. It is distinct from
690	     * the user-facing region reported as the owner's {@code locality} (see
691	     * {@link OwnerMapper#locality(Owner)}), which is read back from the issued identity.
692	     *
693	     * @param owner the owner whose identity region code is wanted
694	     * @return the canonical region code embedded in the owner's identifiers, or
695	     *         {@link Region#UNKNOWN_CODE} when neither the postcode nor the city resolves
696	     */
697	    private String identityRegionCode(Owner owner) {
698	        return Region.code(owner.getPostcode(), owner.getCity());
699	    }
