701	    /**
702	     * Ensures the given {@code base} identifier does not collide with an existing owner's identifier of
703	     * the same kind, read from each owner by {@code identifier}. When no existing owner carries the base
704	     * value it is returned unchanged; otherwise {@code '-<n>'} is appended with the smallest {@code n} of
705	     * 2 or more that yields a value held by no existing owner. Owners for which {@code identifier} yields
706	     * {@code null} are ignored (a {@code null} never collides). Written field-agnostically - like the
707	     * create endpoint's other owner scans ({@link #findExistingOwner(Function, String)},
708	     * {@link #countOwners(Predicate)}) - so the collision search lives in exactly one place and each
709	     * caller supplies only which identifier it de-duplicates.
710	     *
711	     * @param base the computed base identifier to make unique among existing owners
712	     * @param identifier reads the identifier of the same kind from an existing owner (may return {@code null})
713	     * @return the base value, or a {@code '<base>-<n>'} variant that is unique among existing owners
714	     */
715	    private String deduplicate(String base, Function<Owner, String> identifier) {
716	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
717	            .map(identifier)
718	            .filter(java.util.Objects::nonNull)
719	            .collect(java.util.stream.Collectors.toSet());
720	        if (!existing.contains(base)) {
721	            return base;
722	        }
723	        int n = 2;
724	        while (existing.contains(base + "-" + n)) {
725	            n++;
726	        }
727	        return base + "-" + n;
728	    }
