859	    /**
860	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
861	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
862	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
863	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
864	     * value - whether supplied in the request or defaulted to the server date - is stored as the
865	     * next business day, and every value derived from the registration date (such as the membership
866	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
867	     *
868	     * @param date the effective registration date
869	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
870	     */
871	    private LocalDate businessDay(LocalDate date) {
872	        while (isNonBusinessDay(date)) {
873	            date = date.plusDays(1);
874	        }
875	        return date;
876	    }
