878	    /**
879	     * Whether the given date is a weekend day or a listed public holiday, and so not a business day.
880	     *
881	     * @param date the date to test
882	     * @return {@code true} for a Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday}
883	     */
884	    private boolean isNonBusinessDay(LocalDate date) {
885	        DayOfWeek dayOfWeek = date.getDayOfWeek();
886	        return dayOfWeek == DayOfWeek.SATURDAY
887	            || dayOfWeek == DayOfWeek.SUNDAY
888	            || PUBLIC_HOLIDAYS.contains(date);
889	    }
