958	     * @throws DuplicateOwnerIdentityException if an existing (non-deleted) owner has the same identity key
959	     */
960	    private void rejectDuplicateIdentity(Owner owner) {
961	        String key = identityKey(owner);
962	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
963	        if (duplicate) {
