968	    /**
969	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
970	     * first existing owner whose {@code identityKey} <em>differs</em> from this owner's yet whose
971	     * {@code lastName} has the same {@linkplain Soundex#encode(String) Soundex code} and whose
972	     * {@code postcode} is equal, or {@code null} when no such owner exists. Because the telephone is
973	     * part of the identity key, an existing owner sharing this owner's last-name sound and postcode but
974	     * carrying a different telephone has a different identity key: it is not a hard duplicate (it passed
975	     * {@link #rejectDuplicateIdentity(Owner)}) and is surfaced here as a soft match instead. An existing
976	     * owner with the <em>same</em> identity key would already have been rejected as a 409 and so is
977	     * excluded by the differing-key condition. A blank {@code postcode} never matches, since two owners
978	     * without a postcode do not share one. The captured id is stored on the new owner and surfaced as
979	     * the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
980	     *
981	     * @param owner the fully-populated owner being created (telephone normalized)
982	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
983	     */
984	    private Integer possibleDuplicateOf(Owner owner) {
985	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
986	            return null;
987	        }
988	        String key = identityKey(owner);
989	        String lastNameSoundex = soundex.encode(owner.getLastName());
990	        return this.clinicService.findAllOwners().stream()
991	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode())
992	                && lastNameSoundex.equals(soundex.encode(existing.getLastName()))
993	                && !key.equals(identityKey(existing)))
994	            .map(Owner::getId)
995	            .filter(java.util.Objects::nonNull)
996	            .findFirst()
997	            .orElse(null);
998	    }
999	
1000	    /**
1001	     * Reduces an owner to its derived {@code identityKey}: the full lower-case SHA-256 hex digest (see
1002	     * {@link Sha256Hasher#hex(String)}) over {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'} -
1003	     * the owner's telephone reduced to its canonical E.164 form (see
1004	     * {@link TelephoneNormalizer#canonicalize(String)}), the owner's normalized (lower-cased) email or
1005	     * the empty string when absent (see {@link EmailNormalizer#normalize(String)}), and the
1006	     * {@linkplain Soundex#encode(String) Soundex code} of the owner's last name, joined by {@code '|'}.
1007	     * Two owners are duplicates exactly when their whole identity keys are equal. The hashed input never
1008	     * contains {@code null} segments, so the create endpoint's single duplicate check compares this one
1009	     * value across owners.
1010	     *
1011	     * @param owner the owner to derive the identity key for
1012	     * @return the owner's identity key, a 64-character lower-case hex string
1013	     */
1014	    private String identityKey(Owner owner) {
1015	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
1016	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
1017	        String email = normalizedEmail == null ? "" : normalizedEmail;
1018	        String lastNameSoundex = soundex.encode(owner.getLastName());
1019	        return sha256Hasher.hex(telephone + "|" + email + "|" + lastNameSoundex);
1020	    }
1021	
1022	    /**
1023	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
1024	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
1025	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
1026	     * checks reduce both an existing owner and the owner being created to the same canonical key;
1027	     * this returns the matched existing owner itself, so a caller can either reject the collision or
1028	     * record which owner was matched. Owners flagged deleted (soft-deleted) are excluded, so a
1029	     * collision with only a deleted owner is not reported and the create is allowed.
1030	     *
1031	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
1032	     * @param key the canonical key of the owner being created
1033	     * @return the first existing owner sharing the key, or empty when none does
1034	     */
1035	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
1036	        return this.clinicService.findAllOwners().stream()
1037	            .filter(owner -> !owner.isDeleted())
1038	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
1039	            .findFirst();
1040	    }
1041	
1042	    /**
1043	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
1044	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
1045	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
1046	     * being created to the same canonical key and reject a match.
1047	     *
1048	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
1049	     * @param key the canonical key of the owner being created
1050	     * @return {@code true} if some existing owner shares the key
1051	     */
1052	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
1053	        return findExistingOwner(keyExtractor, key).isPresent();
1054	    }
1055	
1056	    /**
1057	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
1058	     * count-based rules - the per-city capacity, the per-day create limit and the derived
1059	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
1060	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
1061	     * place and each rule supplies just its own predicate.
1062	     *
1063	     * @param predicate the condition an owner must satisfy to be counted
1064	     * @return the number of existing owners that satisfy the predicate
1065	     */
1066	    private long countOwners(Predicate<Owner> predicate) {
1067	        return this.clinicService.findAllOwners().stream()
1068	            .filter(predicate)
1069	            .count();
1070	    }
1071	
1072	    /**
1073	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
1074	     * shared {@code householdId}.
1075	     */
1076	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
1077	
1078	    /**
1079	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
1080	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
1081	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
1082	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
1083	     *
1084	     * @param value the raw field value, or {@code null}
1085	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
1086	     */
1087	    private String canonicalizeHousehold(String value) {
1088	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
1089	    }
1090	
1091	    /**
1092	     * Number of leading hex characters of the household hash retained as the shared
1093	     * {@code householdId}.
1094	     */
1095	    private static final int HOUSEHOLD_ID_LENGTH = 12;
1096	
1097	    /**
1098	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
1099	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
1100	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
1101	     * for the last-name normalization), so every owner with the same last name and postcode -
1102	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
1103	     * a postcode have no household basis and are given no household id ({@code null}).
1104	     *
1105	     * @param owner the owner being created
1106	     * @return the shared household identifier, or {@code null} when the owner has no postcode
1107	     */
1108	    private String householdId(Owner owner) {
1109	        String postcode = owner.getPostcode();
1110	        if (postcode == null || postcode.isBlank()) {
1111	            return null;
1112	        }
1113	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
1114	        return sha256Hasher.hexPrefix(key, HOUSEHOLD_ID_LENGTH);
1115	    }
1116	
1117	    /**
1118	     * Counts the owners in the given owner's household: the existing owners that share its
1119	     * {@code householdId} (see {@link #householdId(Owner)}), which - because the owner being counted is
1120	     * itself persisted before it is decorated - includes the owner. An owner with no {@code householdId}
1121	     * (e.g. no postcode) has no shared household and counts as a household of one. The value feeds the
1122	     * household factor of the owner's membership points.
1123	     *
1124	     * @param owner the owner whose household size is being derived
1125	     * @return the number of owners in the owner's household (at least {@code 1})
1126	     */
1127	    private int householdSize(Owner owner) {
1128	        if (owner.getHouseholdId() == null) {
1129	            return 1;
1130	        }
1131	        return householdMembers(owner).size();
1132	    }
1133	
1134	    /**
1135	     * The existing owners that make up the given owner's household: those sharing its
1136	     * {@code householdId} (see {@link #householdId(Owner)}). An owner with no {@code householdId}
1137	     * (e.g. no postcode) belongs to no shared household, so the result is empty. Whether the owner
1138	     * itself appears depends on when the scan runs relative to the create's save: a scan taken after
1139	     * the owner is persisted (as the {@link #householdSize(Owner) household size} derivation is)
1140	     * counts it among its household, while one taken before the save sees only the owners already
1141	     * present. Holding the household lookup in one place lets every household-derived value read the
1142	     * same set of members.
1143	     *
1144	     * @param owner the owner whose household members are wanted
1145	     * @return the owners sharing the owner's household, or an empty list when it has no household
1146	     */
1147	    private List<Owner> householdMembers(Owner owner) {
1148	        String household = owner.getHouseholdId();
1149	        if (household == null) {
1150	            return List.of();
1151	        }
1152	        return this.clinicService.findAllOwners().stream()
1153	            .filter(existing -> household.equals(existing.getHouseholdId()))
1154	            .toList();
1155	    }
1156	}
